package com.bank.cfn.model;

// One managed resource, with flags that cause rollback to fail.
public class StackResource {
    private final String logicalId;
    private final String type;
    private boolean manuallyModified;  // drift: edited outside CloudFormation
    private boolean deletedOutside;    // removed outside CloudFormation
    private boolean rollbackPermitted; // does the deploy role allow rollback actions?
    private String statusReason;

    public StackResource(String logicalId, String type) {
        this.logicalId = logicalId;
        this.type = type;
        this.rollbackPermitted = true;
    }

    public String getLogicalId() { return logicalId; }
    public String getType() { return type; }
    public boolean isManuallyModified() { return manuallyModified; }
    public boolean isDeletedOutside() { return deletedOutside; }
    public boolean isRollbackPermitted() { return rollbackPermitted; }
    public String getStatusReason() { return statusReason; }

    public void setManuallyModified(boolean v) { this.manuallyModified = v; }
    public void setDeletedOutside(boolean v) { this.deletedOutside = v; }
    public void setRollbackPermitted(boolean v) { this.rollbackPermitted = v; }
    public void setStatusReason(String r) { this.statusReason = r; }

    // Can this resource be rolled back cleanly right now?
    public boolean canRollback() {
        if (deletedOutside) { statusReason = "resource deleted outside CloudFormation"; return false; }
        if (manuallyModified) { statusReason = "resource drifted — live state != recorded state"; return false; }
        if (!rollbackPermitted) { statusReason = "deploy role lacks permission for rollback action"; return false; }
        return true;
    }
}
