package com.bank.cfn.engine;

import com.bank.cfn.model.*;
import java.util.*;
import java.util.logging.Logger;

// A tiny CloudFormation-like engine that demonstrates the stuck-rollback flow.
public class CloudFormationEngine {
    private static final Logger log = Logger.getLogger(CloudFormationEngine.class.getName());

    // Submit an update that fails on one resource and triggers automatic rollback.
    public void update(Stack stack, String failingResourceId) {
        stack.setStatus(StackStatus.UPDATE_IN_PROGRESS);
        log.info(() -> "Update started on stack " + stack.getName());
        log.severe(() -> "Resource " + failingResourceId + " failed to update — starting rollback");
        rollback(stack);
    }

    // Automatic rollback: tries to restore every resource. If any cannot, stack sticks.
    private void rollback(Stack stack) {
        stack.setStatus(StackStatus.UPDATE_ROLLBACK_IN_PROGRESS);
        List<StackResource> blockers = new ArrayList<>();
        for (StackResource r : stack.getResources()) {
            if (!r.canRollback()) {
                blockers.add(r);
                log.severe(() -> "Rollback FAILED for " + r.getLogicalId() + ": " + r.getStatusReason());
            }
        }
        if (blockers.isEmpty()) {
            stack.setStatus(StackStatus.UPDATE_ROLLBACK_COMPLETE);
            log.info(() -> "Rollback complete — stack is stable again");
        } else {
            stack.setStatus(StackStatus.UPDATE_ROLLBACK_FAILED);
            log.severe(() -> "Stack " + stack.getName() + " is STUCK in UPDATE_ROLLBACK_FAILED ("
                    + blockers.size() + " blocker(s))");
        }
    }

    // Diagnosis: report every resource blocking the rollback.
    public List<StackResource> diagnose(Stack stack) {
        List<StackResource> blockers = new ArrayList<>();
        for (StackResource r : stack.getResources()) {
            if (!r.canRollback()) blockers.add(r);
        }
        blockers.forEach(r -> log.warning(() -> "BLOCKER " + r.getLogicalId() + " → " + r.getStatusReason()));
        return blockers;
    }

    // Recovery: retry the rollback, skipping resources that cannot be reconciled.
    public void continueUpdateRollback(Stack stack, Set<String> resourcesToSkip) {
        if (stack.getStatus() != StackStatus.UPDATE_ROLLBACK_FAILED) {
            log.warning(() -> "continue-update-rollback only valid from UPDATE_ROLLBACK_FAILED");
            return;
        }
        stack.setStatus(StackStatus.UPDATE_ROLLBACK_IN_PROGRESS);
        List<StackResource> stillBlocking = new ArrayList<>();
        for (StackResource r : stack.getResources()) {
            if (resourcesToSkip.contains(r.getLogicalId())) {
                log.warning(() -> "SKIPPING " + r.getLogicalId() + " — must reconcile manually afterwards");
                continue;
            }
            if (!r.canRollback()) stillBlocking.add(r);
        }
        if (stillBlocking.isEmpty()) {
            stack.setStatus(StackStatus.UPDATE_ROLLBACK_COMPLETE);
            log.info(() -> "continue-update-rollback succeeded — stack is UPDATE_ROLLBACK_COMPLETE");
        } else {
            stack.setStatus(StackStatus.UPDATE_ROLLBACK_FAILED);
            log.severe(() -> "Still stuck — " + stillBlocking.size() + " resource(s) not fixed or skipped");
        }
    }
}
