package com.bank.cfn;

import com.bank.cfn.engine.CloudFormationEngine;
import com.bank.cfn.model.*;
import java.util.*;
import java.util.logging.*;

public class CfnRecoveryApplication {
    private static final Logger log = Logger.getLogger(CfnRecoveryApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CfnLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Build the payments stack with three resources.
        StackResource sg = new StackResource("PaymentsSecurityGroup", "AWS::EC2::SecurityGroup");
        StackResource db = new StackResource("PaymentsDatabase", "AWS::RDS::DBInstance");
        StackResource bucket = new StackResource("PaymentsArchiveBucket", "AWS::S3::Bucket");

        // Cause 1: drift — someone hand-edited the security group.
        sg.setManuallyModified(true);
        // Cause 2: insufficient permission — deploy role cannot delete the DB rule it added.
        db.setRollbackPermitted(false);
        // Cause 3: resource deleted entirely outside CloudFormation.
        bucket.setDeletedOutside(true);

        Stack stack = new Stack("bank-payments", List.of(sg, db, bucket));
        CloudFormationEngine cfn = new CloudFormationEngine();

        // Update fails and the automatic rollback gets stuck.
        cfn.update(stack, "PaymentsDatabase");
        log.info(() -> "Stack status now: " + stack.getStatus());

        // Diagnose the blockers from the stack events.
        cfn.diagnose(stack);

        // Fix out of band: restore the drifted SG, grant the missing permission.
        sg.setManuallyModified(false);           // reconciled drift
        db.setRollbackPermitted(true);           // added IAM permission to deploy role
        // The bucket is gone for good — it must be skipped.
        cfn.continueUpdateRollback(stack, Set.of("PaymentsArchiveBucket"));
        log.info(() -> "Final stack status: " + stack.getStatus());
    }
}

